Fixes: 79d442461df74 ("locking/xchg/alpha: Clean up barrier usage by using smp_mb() in place of __ASM__MB")
Link: http://lkml.kernel.org/r/1519704058-13430-1-git-send-email-parri.andrea@gmail.com
Signed-off-by: Ingo Molnar <mingo@kernel.org>

Here is the root cause:
The root cause of the bug was the introduction of unnecessary memory barriers in the `_local()` variants of atomic operations on the Alpha architecture. These barriers were added in previous commits, which led to incorrect memory ordering and potential performance issues. The original implementation avoided these barriers to ensure efficient operation, but the changes inadvertently compromised the intended behavior of the atomic operations.

Here is the patch:
  * Since it can be used to implement critical sections
  * it must clobber "memory" (also for interrupts in UP).
- *
- * The leading and the trailing memory barriers guarantee that these
- * operations are fully ordered.
- *
  */

 	unsigned long ret, tmp, addr64;

-	smp_mb();
 	__asm__ __volatile__(
 	"	andnot	%4,7,%3\n"
 	: "=&r" (ret), "=&r" (val), "=&r" (tmp), "=&r" (addr64)
 	: "r" ((long)m), "1" (val) : "memory");
-	smp_mb();

 	return ret;
 	unsigned long ret, tmp, addr64;

-	smp_mb();
 	__asm__ __volatile__(
 	"	andnot	%4,7,%3\n"
 	: "=&r" (ret), "=&r" (val), "=&r" (tmp), "=&r" (addr64)
 	: "r" ((long)m), "1" (val) : "memory");
-	smp_mb();

 	return ret;
 	unsigned long dummy;

-	smp_mb();
 	__asm__ __volatile__(
 	"1:	ldl_l %0,%4\n"
 	: "=&r" (val), "=&r" (dummy), "=m" (*m)
 	: "rI" (val), "m" (*m) : "memory");
-	smp_mb();

 	return val;
 	unsigned long dummy;

-	smp_mb();
 	__asm__ __volatile__(
 	"1:	ldq_l %0,%4\n"
 	: "=&r" (val), "=&r" (dummy), "=m" (*m)
 	: "rI" (val), "m" (*m) : "memory");
-	smp_mb();

 	return val;
  * store NEW in MEM.  Return the initial value in MEM.  Success is
  * indicated by comparing RETURN with OLD.
- *
- * The leading and the trailing memory barriers guarantee that these
- * operations are fully ordered.
- *
- * The trailing memory barrier is placed in SMP unconditionally, in
- * order to guarantee that dependency ordering is preserved when a
- * dependency is headed by an unsuccessful operation.
  */

 	unsigned long prev, tmp, cmp, addr64;

-	smp_mb();
 	__asm__ __volatile__(
 	"	andnot	%5,7,%4\n"
 	: "=&r" (prev), "=&r" (new), "=&r" (tmp), "=&r" (cmp), "=&r" (addr64)
 	: "r" ((long)m), "Ir" (old), "1" (new) : "memory");
-	smp_mb();

 	return prev;
 	unsigned long prev, tmp, cmp, addr64;

-	smp_mb();
 	__asm__ __volatile__(
 	"	andnot	%5,7,%4\n"
 	: "=&r" (prev), "=&r" (new), "=&r" (tmp), "=&r" (cmp), "=&r" (addr64)
 	: "r" ((long)m), "Ir" (old), "1" (new) : "memory");
-	smp_mb();

 	return prev;
 	unsigned long prev, cmp;

-	smp_mb();
 	__asm__ __volatile__(
 	"1:	ldl_l %0,%5\n"
 	: "=&r"(prev), "=&r"(cmp), "=m"(*m)
 	: "r"((long) old), "r"(new), "m"(*m) : "memory");
-	smp_mb();

 	return prev;
 	unsigned long prev, cmp;

-	smp_mb();
 	__asm__ __volatile__(
 	"1:	ldq_l %0,%5\n"
 	: "=&r"(prev), "=&r"(cmp), "=m"(*m)
 	: "r"((long) old), "r"(new), "m"(*m) : "memory");
-	smp_mb();

 	return prev;


